    dict(key='29-class-6', kind='code', title='PolicyRule — a star covers what is below it',
         body='// PolicyRule: a teaching class: decides a read the way the policy does\nif (path.endsWith("*")) {\n    return request.startsWith(path.substring(0, path.length() - 1));\n}\nreturn request.equals(path);',
         narration="A rule that ends in a star covers every path that starts with the rest. [[slnc 300]] Any other rule covers only its own path. [[slnc 300]] The demo prints its answer next to the real server's, and they agree."),
